def _fecha_ultimo_guardado_git(raiz, destino):
    """Devuelve en segundos la fecha del ultimo guardado en git del archivo de destino.

    Pregunta a git con git log -1 y el formato de fecha en segundos. Si git no contesta
    (no hay git, no hay historial, falla la orden o la salida no es un numero), devuelve
    None. Nunca revienta.
    """
    try:
        resultado = subprocess.run(
            ["git", "log", "-1", "--format=%ct", "--", destino],
            cwd=raiz,
            capture_output=True,
            text=True,
        )
    except OSError:
        return None
    if resultado.returncode != 0:
        return None
    salida = resultado.stdout.strip()
    if not salida:
        return None
    try:
        return int(salida)
    except ValueError:
        return None


def _es_copia_vieja(raiz, destino, origen):
    """Dice si la copia apartada es de antes del ultimo guardado en git del destino.

    Compara la fecha del ultimo guardado en git del archivo de destino con la fecha de
    la copia apartada. Si el ultimo guardado es mas nuevo que la copia, la copia es de
    antes y devuelve True. Si git no contesta, devuelve False (se devuelve como hoy).
    OJO: no se compara con la fecha del archivo que hay ahora en el disco, porque el
    guardia lo restaura justo despues de apartar la copia y siempre parece mas nuevo.
    """
    fecha_git = _fecha_ultimo_guardado_git(raiz, destino)
    if fecha_git is None:
        return False
    try:
        fecha_copia = os.path.getmtime(origen)
    except OSError:
        return False
    return fecha_git > fecha_copia
